(() => {
  'use strict';
  const C=OSLabConcurrencyMovies,P=C.phase,E=C.esc,pick=C.select,node=C.node,badge=C.badge,page=document.body.dataset.page;
  const click=(attr,value)=>document.querySelector('['+attr+'="'+value+'"]')?.click();
  function hash(){const detail=C.wrap('hash-flow',['#hash-demo'],'获取、插入与释放的逐轮记录');C.mount({id:'hash-flow',before:detail,controls:['[data-hash]'],action:()=>click('data-hash',pick('data-hash','separate')==='separate'?'hot':'separate'),actionLabel:()=>pick('data-hash','separate')==='separate'?'让两人访问同一桶':'改为访问不同桶',
    build(){const workload=pick('data-hash','separate'),a=OSLabConcurrentStructures.hashTrace('table',workload),b=OSLabConcurrentStructures.hashTrace('bucket',workload),frames=Array.from({length:Math.max(a.length,b.length)},(_,i)=>({table:a[Math.min(i,a.length-1)],bucket:b[Math.min(i,b.length-1)]}));const phases=frames.map((s,i)=>{const before=frames[i-1],moves=[];if(i)for(const scope of ['table','bucket'])for(const t of s[scope].threads)if(s[scope].buckets[t.key%4].includes(t.key)&&!before[scope].buckets[t.key%4].includes(t.key))moves.push({from:scope+'-'+t.id,to:scope+'-bucket-'+(t.key%4),text:t.key,type:'cm-key'});return P(s,i===0?'同样两个插入，只改变锁的范围':workload==='separate'?(i===1?'整表锁挡住 B；分桶锁允许两人分别进入':i===2?'不同桶可以各自插入，无须排队':'分桶方案已完成，整表方案继续放行'):'访问同一个桶，两种方案都必须等待',workload==='separate'?'A 访问桶 0，B 访问桶 1。锁覆盖无关的桶，也会把本可独立的操作挡住。':'A、B 都修改桶 0；拆分其他桶的锁，并不能取消这里的互斥。',{duration:1400,before,moves,id:'round-'+i,during:'键正在放入各自受保护的桶'});});phases.push(P(frames.at(-1),workload==='separate'?'缩小锁的范围，消除了无关数据之间的等待':'同一桶上的竞争仍然存在','两组都完成了两个插入。这里比较等待关系，不把动画轮次当作性能测量。',{duration:1000,id:'result'}));return{context:'固定 4 个桶，没有扩容或跨桶操作',workload,phases};},
    view(pair){return '<div class="cm-hash">'+['table','bucket'].map(scope=>{const s=pair[scope];return '<section class="cm-hash-case"><h4>'+ (scope==='table'?'一把锁保护整张表':'每个桶分别加锁')+'</h4><div class="cm-key-submit">'+s.threads.map(t=>'<span class="cm-submit '+(t.status==='等待锁'?'cm-blocked':'')+'" data-node="'+scope+'-'+t.id+'">'+badge(t.id)+' 键 '+t.key+(t.status==='等待锁'?'<b>被锁挡住</b>':'')+'</span>').join('')+'</div><div class="cm-bucket-row '+(scope==='table'&&s.locks[0]?'cm-table-guard':'')+'">'+s.buckets.map((items,j)=>'<div class="cm-bucket '+(scope==='bucket'&&s.locks[j]?'cm-bucket-guard':'')+'" data-node="'+scope+'-bucket-'+j+'"><span>桶 '+j+'</span><strong>'+items.join(' · ')+'</strong><small>'+ (scope==='bucket'&&s.locks[j]?s.locks[j]+' 持锁':'')+'</small></div>').join('')+'</div><div class="cm-mini-result">'+(scope==='table'?'整表锁：'+(s.locks[0]||'空闲'):'桶锁分别保护对应数据')+'<b>完成 '+s.completed+' / 2</b></div></section>';}).join('')+'</div>';}
  });}
  function waiting(){const section=document.getElementById('waiting'),detail=C.wrap('wait-flow',['#wait-conditions',section.querySelector('.cc-wait-comparison'),section.querySelector('.cc-legend'),section.querySelector('.cc-transport')],'逐单位 CPU 调度与计量记录');document.getElementById('wait-result')&&detail.append(document.getElementById('wait-result'));
    C.mount({id:'wait-flow',before:detail,controls:['[data-cores]','#wait-hold'],action:()=>click('data-cores',pick('data-cores','1')==='1'?'2':'1'),actionLabel:()=>pick('data-cores','1')==='1'?'对照双核':'对照单核',build(){const cores=Number(pick('data-cores','1')),hold=Number(document.getElementById('wait-hold').value),traces=Object.fromEntries(['spin','block'].map(strategy=>[strategy,OSLabConcurrency.waitingTrace({strategy,cores,hold})])),length=Math.max(...Object.values(traces).map(t=>t.length));const frames=Array.from({length},(_,i)=>Object.fromEntries(['spin','block'].map(k=>[k,traces[k][Math.min(i,traces[k].length-1)]])));const phases=frames.map((s,i)=>{const before=frames[i-1],moves=[];if(i)for(const k of ['spin','block'])if(s[k].remaining<before[k].remaining)moves.push({from:k+'-work',to:k+'-finished',text:'1',type:'cm-work-unit'});return P(s,i===0?'A 持锁做完工作后，B 才能继续':s.spin.done&&s.block.done?'两组都完成相同工作':cores===1?(s.spin.remaining>s.block.remaining?'阻塞方案的 A 已多完成 '+(s.spin.remaining-s.block.remaining)+' 单位工作':s.spin.lanes[0].at(-1)?.kind==='spin'?'自旋在 CPU 上试锁，阻塞开始让出 CPU':'两边的 A 都在推进持锁工作'):'双核上 A 持续运行，B 的等待仍可能占 CPU',i===0?'看 A 的剩余工作是否减少，以及 B 等待期间是否仍占着 CPU。':cores===1?'比较 A 的剩余工作与等待开销。自旋失败所占的 CPU 时间，没有推进 A 的工作。':'A 在自己的核心上推进工作。另一核心自旋会反复试锁；阻塞后则可空闲或执行其他工作。',{duration:i?850:1200,travel:500,before,moves,id:'time-'+i,during:'CPU 正在推进本轮能够执行的工作'});});const last=frames.at(-1);phases.push(P(last,'自旋等待开销 '+last.spin.overhead+'；阻塞等待开销 '+last.block.overhead,hold===1?'短暂持锁时，阻塞登记和唤醒的固定成本可能更明显。不能只按名称判断快慢。':cores===1?'B 阻塞后退出 CPU 竞争，A 能更连续地做完持锁工作。':'自旋没有夺走另一核心上的 A，但仍消耗 B 所在核心的 CPU 时间。',{duration:1000,id:'result'}));return{context:cores+' 核；A 还需 '+hold+' 单位工作，B 需 1 单位',cores,hold,phases};},
      view(pair,{story,phase,moving}){return '<div class="cm-wait-compare">'+['spin','block'].map(k=>{const s=pair[k],now=moving?phase.state[k]:s;return '<section class="cm-wait-case"><h4>'+ (k==='spin'?'自旋：反复尝试':'阻塞：退出竞争')+'</h4><div class="cm-cpu-row">'+now.lanes.map((lane,i)=>{const tick=lane.at(-1);return '<div class="cm-cpu '+(tick?.kind==='spin'?'cm-spinning':'')+'"><span>CPU '+(i+1)+'</span><strong>'+E(now.done?'空闲':tick?.actor||'空闲')+'</strong><small>'+E(now.done?'工作已结束':({spin:'重复检查锁',work:'推进工作',overhead:tick?.label==='眠'?'登记阻塞':'唤醒 B',acquire:'获取成功',idle:'无可运行工作'}[tick?.kind]||'准备运行'))+'</small></div>';}).join('')+'<div class="cm-outside '+(s.b==='blocked'?'cm-asleep':'')+'">'+badge('B')+'<span>'+({waiting:'等待获取锁',blocked:'阻塞，不占 CPU',inside:'已获得锁',done:'工作完成'}[s.b])+'</span></div></div><div class="cm-work-meter"><span>A 还需 '+s.remaining+'</span><div data-node="'+k+'-work">'+Array.from({length:story.hold},(_,i)=>'<i class="'+(i<s.remaining?'cm-work-left':'cm-work-done')+'"></i>').join('')+'</div><b data-node="'+k+'-finished">已完成 '+(story.hold-s.remaining)+'</b></div><p class="cm-mini-result">等待管理占用 CPU <b>'+s.overhead+' 单位</b></p></section>';}).join('')+'</div>';}
    });}
  function events(){const detail=C.wrap('event-flow',['#event-conditions','#event-demo'],'逐单位执行与请求上下文');C.mount({id:'event-flow',before:detail,controls:['[data-event-kind]','[data-event-cost]'],action:()=>click('data-event-kind',pick('data-event-kind','io')==='io'?'cpu':'io'),actionLabel:()=>pick('data-event-kind','io')==='io'?'对照长计算':'对照 I/O 等待',build(){const kind=pick('data-event-kind','io'),cost=Number(pick('data-event-cost','4')),traces=Object.fromEntries(['blocking','cooperative'].map(mode=>[mode,OSLabEvents.trace(kind,mode,cost)])),length=Math.max(...Object.values(traces).map(t=>t.length)),frames=Array.from({length},(_,i)=>Object.fromEntries(['blocking','cooperative'].map(k=>[k,traces[k][Math.min(i,traces[k].length-1)]])));const phases=frames.map((s,i)=>{const before=frames[i-1],moves=[];if(i)for(const k of ['blocking','cooperative'])for(const who of ['A','B'])if(s[k].done[who]!==null&&before[k].done[who]===null)moves.push({from:k+'-cpu',to:k+'-done-'+who,text:who,type:'cm-request-'+who});return P(s,!i?'A 先到，B 在下一单位到达':kind==='io'?(s.cooperative.done.B!==null&&s.blocking.done.B===null?'同样还在等 I/O，异步方案已经处理完 B':'I/O 自行推进，CPU 是否被它占住决定 B 能否响应'):'切分 A 的计算，让 B 在中间得到处理',kind==='io'?'两边 I/O 的用时相同。B 只需要一个单位 CPU；差别在于循环能否接手它。':'切分没有减少 A 的计算量，只改变 B 什么时候能得到执行机会。',{duration:i?950:1100,travel:550,before,moves,id:'time-'+i,during:'就绪请求正在完成处理'});});const last=frames.at(-1);phases.push(P(last,'B：完整处理函数在 t='+last.blocking.done.B+' 完成；及时返回在 t='+last.cooperative.done.B+' 完成',kind==='io'?'异步 I/O 提前处理了 B，并没有让设备读取本身更快。':'A 的总计算量保持不变。改善的是 B 的响应时间，不是凭空增加 CPU 算力。',{duration:1200,id:'result'}));return{context:'每组只有一个事件循环线程；A、B 的工作量相同',kind,cost,phases};},
      view(pair,{story,phase,moving}){return '<div class="cm-events">'+['blocking','cooperative'].map(k=>{const s=pair[k],now=moving?phase.state[k]:s,entry=now.history.at(-1),ended=Object.values(s.done).every(v=>v!==null),io=story.kind==='io',doneWork=s.history.filter(t=>t.actor==='A'&&t.activity==='work').length,progress=io?Math.min(story.cost,Math.max(0,s.time-1)):doneWork,total=io?story.cost:story.cost+2;return '<section class="cm-event-case"><h4>'+(k==='blocking'?(io?'阻塞调用':'完整长函数'):(io?'异步提交':'分段后返回循环'))+'</h4><div class="cm-event-main"><div class="cm-cpu '+(entry?.activity==='blocked'?'cm-frozen':'')+'" data-node="'+k+'-cpu"><span>唯一的事件线程</span><strong>'+E(ended?'完成':entry?.actor||'等待')+'</strong><small>'+E(ended?'均已处理':entry?.activity==='blocked'?'被 A 的 I/O 阻塞':entry?.activity==='idle'?'没有就绪事件':entry?.actor?'处理 '+entry.actor:'准备处理')+'</small></div><div class="cm-request-status"><div data-node="'+k+'-done-A">'+badge('A')+' '+(s.done.A!==null?'完成 · t='+s.done.A:io?'等数据后继续':'计算中')+'</div><div data-node="'+k+'-done-B" class="'+(s.done.B!==null?'cm-b-done':s.time>=1?'cm-b-pending':'cm-b-future')+'">'+badge('B')+' '+(s.done.B!==null?'已完成 · t='+s.done.B:s.time?'等待处理':'下一单位到达')+'</div></div></div><div class="cm-io-meter"><span>'+(io?'A 的设备 I/O':'A 已完成计算')+'</span><div><i style="width:'+progress/total*100+'%"></i></div><b>'+progress+' / '+total+'</b></div></section>';}).join('')+'</div>';}
  });}
  if(page==='concurrentStructures')hash();if(page==='locks')waiting();if(page==='events')events();
})();
